// dashboard.mjs — weekly wait-time summary for the front desk.
// Spec: README.md. Timestamps are local clinic wall-clock "YYYY-MM-DD HH:MM"; we parse them as UTC
// on purpose so the host machine's time zone / DST can never change a wait or a week.
import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

export function parse(text) {
  const lines = text.replace(/^﻿/, '').split(/\r?\n/).filter((l) => l.trim() !== '');
  if (!lines.length) return [];
  const cols = lines[0].split(',').map((c) => c.trim());
  return lines.slice(1).map((l) => Object.fromEntries(l.split(',').map((v, i) => [cols[i], v.trim()])));
}

const TS = /^(\d{4})-(\d{2})-(\d{2}) (\d{2}):(\d{2})$/;
function wallMs(ts) {
  const m = TS.exec(ts);
  if (!m) throw new Error(`bad timestamp: ${JSON.stringify(ts)}`);
  const [, y, mo, d, h, mi] = m.map(Number);
  const ms = Date.UTC(y, mo - 1, d, h, mi);
  const back = new Date(ms);
  if (back.getUTCDate() !== d || back.getUTCMonth() !== mo - 1 || h > 23 || mi > 59) {
    throw new Error(`bad timestamp: ${JSON.stringify(ts)}`);
  }
  return ms;
}

export const minutes = (a, b) => (wallMs(b) - wallMs(a)) / 60000;

export function weekOf(ts) {
  const d = new Date(wallMs(ts));
  const back = (d.getUTCDay() + 6) % 7; // Monday = 0
  d.setUTCDate(d.getUTCDate() - back);
  return d.toISOString().slice(0, 10);
}

export function median(xs) {
  const s = [...xs].sort((a, b) => a - b);
  const n = s.length;
  if (!n) return null;
  return n % 2 ? s[(n - 1) / 2] : (s[n / 2 - 1] + s[n / 2]) / 2;
}

export function summarize(rows) {
  const weeks = new Map();
  for (const r of rows) {
    const w = weekOf(r.signed_in);
    if (!weeks.has(w)) weeks.set(w, { visits: 0, waits: [] });
    const e = weeks.get(w);
    e.visits++;
    if (r.seen_at) e.waits.push(minutes(r.signed_in, r.seen_at));
  }
  return [...weeks.keys()].sort().map((week) => {
    const { visits, waits } = weeks.get(week);
    return { week, visits, seen: waits.length, walkouts: visits - waits.length, median_wait_min: median(waits) };
  });
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  if (!process.argv[2]) {
    console.error('usage: node dashboard.mjs visits.csv');
    process.exit(2);
  }
  for (const w of summarize(parse(readFileSync(process.argv[2], 'utf8')))) console.log(JSON.stringify(w));
}

