  if (!ok) bad++;
  console.log(`${ok ? 'ok  ' : 'FAIL'} ${name}${ok ? '' : `: got ${JSON.stringify(got)}, want ${JSON.stringify(want)}`}`);
};
const throws = (name, fn) => {
  let threw = false;
  try { fn(); } catch { threw = true; }
  eq(name, threw, true);
};
const H = 'id,signed_in,seen_at\n';

// median (README: numeric, even count = mean of the two middle values, null if empty)
eq('median of odd count', median([3, 1, 2]), 2);
eq('median of one', median([7]), 7);
eq('median of even count is mean of middle two', median([4, 1, 3, 2]), 2.5);
eq('median sorts numerically, not as strings', median([9, 10, 30]), 10);
eq('median of nothing is null', median([]), null);

// weeks start Monday
eq('one seen visit on a Wednesday', summarize(parse(H + '1,2026-03-04 09:00,2026-03-04 09:12\n')),
  [{ week: '2026-03-02', visits: 1, seen: 1, walkouts: 0, median_wait_min: 12 }]);
eq('Monday is its own week start', weekOf('2026-03-02 08:00'), '2026-03-02');
eq('Sunday belongs to the previous Monday', weekOf('2026-03-08 08:00'), '2026-03-02');
eq('week start can fall in the previous year', weekOf('2026-01-01 09:00'), '2025-12-29');

// walkouts are visits
