  summarize(parse(H + '1,2026-03-04 09:00,2026-03-04 09:10\n2,2026-03-04 09:05,\n3,2026-03-04 09:20,2026-03-04 09:50\n')),
  [{ week: '2026-03-02', visits: 3, seen: 2, walkouts: 1, median_wait_min: 20 }]);
eq('week with only walkouts has median null', summarize(parse(H + '1,2026-03-04 09:00,\n')),
  [{ week: '2026-03-02', visits: 1, seen: 0, walkouts: 1, median_wait_min: null }]);
eq('identical rows count as two visits',
  summarize(parse(H + '1,2026-03-04 09:00,2026-03-04 09:10\n1,2026-03-04 09:00,2026-03-04 09:10\n'))[0].visits, 2);
eq('weeks print in date order', summarize(parse(H + '1,2026-03-10 09:00,2026-03-10 09:10\n2,2026-03-03 09:00,2026-03-03 09:10\n')).map((w) => w.week),
  ['2026-03-02', '2026-03-09']);

// local wall clock, no time zones
eq('wait across a US DST change is wall-clock minutes', minutes('2026-03-08 01:50', '2026-03-08 03:10'), 80);
eq('CRLF and blank lines are tolerated',
  summarize(parse('id,signed_in,seen_at\r\n1,2026-03-04 09:00,2026-03-04 09:12\r\n\r\n')),
  [{ week: '2026-03-02', visits: 1, seen: 1, walkouts: 0, median_wait_min: 12 }]);
throws('malformed signed_in throws, even on a walkout row', () => summarize(parse(H + '1,03/04/2026 9:00,\n')));
throws('impossible date throws', () => summarize(parse(H + '1,2026-02-30 09:00,2026-02-30 09:10\n')));

// the real data
const PINNED = [
  { week: '2026-02-23', visits: 37, seen: 36, walkouts: 1, median_wait_min: 17 },
  { week: '2026-03-02', visits: 44, seen: 42, walkouts: 2, median_wait_min: 16.5 },
  { week: '2026-03-09', visits: 37, seen: 36, walkouts: 1, median_wait_min: 22 },
  { week: '2026-03-16', visits: 37, seen: 33, walkouts: 4, median_wait_min: 31 },
  { week: '2026-03-23', visits: 43, seen: 39, walkouts: 4, median_wait_min: 33 },
  { week: '2026-03-30', visits: 33, seen: 29, walkouts: 4, median_wait_min: 39 },
];
const real = summarize(parse(readFileSync(new URL('./visits.csv', import.meta.url), 'utf8')));
eq('visits.csv weekly table (quoted in NOTE.md)', real, PINNED);
eq('visits.csv: all 231 rows counted', real.reduce((a, w) => a + w.visits, 0), 231);
for (const tz of ['UTC', 'America/Chicago']) {
