// assign.mjs — who works when.
//
// Every rule in POLICY.md is a hard constraint here; nothing is "best effort". The rota is built
// day by day with backtracking: each day tries the pairs of the people furthest behind their fair
// share first, and a branch is abandoned as soon as it can no longer meet some rule (bounds below).
// Ties are broken by a rotation that moves each day, not by name: the old rota's unfairness came
// from an alphabetical sort, and a name-ordered tie-break would bring a little of it back.
import { days, isWeekend } from './calendar.mjs';
import { shares, PER_DAY, TOTAL_SLACK, WEEKEND_SLACK, MAX_RUN } from './policy.mjs';

const EPS = 1e-9;
const NODE_LIMIT = 500000;
const TARGET_LIMIT = 20000;   // per bounds level, shared among its restarts
const RESTARTS = 8;
const FINAL_FIRST = 2000;     // first budget of the final (policy-range) search; doubles per restart

export function makeRota(people, start, n, { nodeLimit = NODE_LIMIT } = {}) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(String(start)) || days(start, 1)[0] !== start) throw new Error(`bad start date: ${start}`);
  if (!Number.isInteger(n) || n < 1) throw new Error(`bad number of days: ${n}`);
  const period = days(start, n);
  const k = people.length;
  const nurse = people.map((p) => p.role === 'nurse');
  const avail = people.map((p) => period.map((d) => !p.leave.has(d)));
  const wkd = period.map(isWeekend);

  for (let i = 0; i < n; i++) {
    const free = people.filter((_, j) => avail[j][i]);
    if (!free.some((p) => p.role === 'nurse')) throw new Error(`no nurse available on ${period[i]}`);
    if (free.length < PER_DAY) throw new Error(`fewer than ${PER_DAY} people available on ${period[i]}`);
  }

  // Rules 4 and 5 as integer ranges.
  const sh = shares(people, start, n);
  const lo = sh.map((s) => Math.max(0, Math.ceil(s.total - TOTAL_SLACK - EPS)));
  const hi = sh.map((s) => Math.floor(s.total + TOTAL_SLACK + EPS));
  const wLo = sh.map((s) => Math.max(0, Math.ceil(s.weekend - WEEKEND_SLACK - EPS)));
  const wHi = sh.map((s) => Math.floor(s.weekend + WEEKEND_SLACK + EPS));

  // Rule 1 needs a nurse every day, but rules 4 and 5 cap each nurse by a share that ignores role.
  // With few or part-time nurses the caps add up to fewer shifts than there are days. That is a
  // conflict inside the policy, not a search failure, so say so in those terms.
  const nurseCap = sh.reduce((a, s, j) => a + (nurse[j] ? hi[j] : 0), 0);
  const nurseWkCap = sh.reduce((a, s, j) => a + (nurse[j] ? wHi[j] : 0), 0);
  const wkDays = wkd.filter(Boolean).length;
  if (nurseCap < n) throw new Error(`policy conflict: ${n} days each need a nurse, but rule 4 caps the nurses at ${nurseCap} shifts between them`);
  if (nurseWkCap < wkDays) throw new Error(`policy conflict: ${wkDays} weekend days each need a nurse, but rule 5 caps the nurses at ${nurseWkCap} weekend shifts between them`);

  checkStretches({ people, period, avail, wkd, nurse, lo, hi, wLo, wHi });

  // most[j][i][r] / mostWk[j][i][r]: the most shifts (weekend shifts) person j could still work
  // from day i on, having already worked r days in a row, given leave and rule 3. Exact DP.
  const table = (weightOf) => avail.map((a) => {
