// people.mjs — load and validate the team file.
import { readFileSync } from 'node:fs';

const DATE = /^\d{4}-\d{2}-\d{2}$/;
const realDate = (d) => DATE.test(d) && new Date(`${d}T00:00:00Z`).toISOString().slice(0, 10) === d;

export function loadPeople(path) {
  return validatePeople(JSON.parse(readFileSync(path, 'utf8')));
}

export function validatePeople(people) {
  if (!Array.isArray(people) || people.length === 0) throw new Error('team must be a non-empty list');
  const seen = new Set();
  for (const p of people) {
    if (!p || typeof p.name !== 'string' || !p.name || !['nurse', 'aide'].includes(p.role))
      throw new Error(`bad person: ${JSON.stringify(p)}`);
    if (seen.has(p.name)) throw new Error(`duplicate name: ${p.name}`);
    seen.add(p.name);
    // POLICY.md: every person *has* an fte. A missing one is a hole in the team file, not "full time";
    // guessing 1 would quietly hand that person a full-timer's share of the shifts.
    if (p.fte === undefined || p.fte === null || p.fte === '') throw new Error(`missing fte for ${p.name}`);
    p.fte = Number(p.fte);
    if (!Number.isFinite(p.fte) || p.fte < 0 || p.fte > 1) throw new Error(`bad fte for ${p.name}: ${p.fte}`);
    const leave = p.leave instanceof Set ? [...p.leave] : p.leave ?? [];
    if (!Array.isArray(leave)) throw new Error(`bad leave for ${p.name}`);
    for (const d of leave) if (!realDate(d)) throw new Error(`bad leave date for ${p.name}: ${d}`);
    p.leave = new Set(leave);
  }
  return people;
}

