// policy.mjs — POLICY.md as code: the fair shares, and a checker that lists every breach.
// assign.mjs builds rotas against these numbers; the tests judge rotas with checkRota.
import { days, isWeekend } from './calendar.mjs';

export const PER_DAY = 2;
export const TOTAL_SLACK = 2;     // rule 4: within 2 of fair share
export const WEEKEND_SLACK = 1.5; // rule 5: within 1.5 of weekend share
export const MAX_RUN = 5;         // rule 3: no more than 5 days in a row
const EPS = 1e-9;                 // shares are fractions; don't let float noise decide a breach

// Rule 4/5 weights and shares, one entry per person (same order as `people`).
export function shares(people, start, n) {
  const period = days(start, n);
  const weekendDays = period.filter(isWeekend).length;
  const weight = people.map((p) => (p.fte * period.filter((d) => !p.leave.has(d)).length) / n);
  const sum = weight.reduce((a, b) => a + b, 0);
  return people.map((p, i) => ({
    name: p.name,
    weight: weight[i],
    total: sum > 0 ? (PER_DAY * n * weight[i]) / sum : 0,
    weekend: sum > 0 ? (PER_DAY * weekendDays * weight[i]) / sum : 0,
  }));
}

// Every way `rota` breaks POLICY.md, as readable strings. Empty array = compliant.
export function checkRota(people, start, n, rota) {
  const out = [];
  const period = days(start, n);
  const byName = new Map(people.map((p) => [p.name, p]));
  const keys = Object.keys(rota);
  if (keys.length !== n || !period.every((d) => d in rota)) out.push('rota does not cover exactly the period');
  const count = new Map(people.map((p) => [p.name, { total: 0, weekend: 0, run: 0 }]));
  for (const d of period) {
    const crew = rota[d] || [];
    if (crew.length !== PER_DAY || new Set(crew).size !== PER_DAY) out.push(`${d}: not exactly ${PER_DAY} different people`);
    if (!crew.some((name) => byName.get(name)?.role === 'nurse')) out.push(`${d}: no nurse`);
    for (const name of crew) {
      const p = byName.get(name);
      if (!p) { out.push(`${d}: unknown person ${name}`); continue; }
      if (p.leave.has(d)) out.push(`${d}: ${name} is on leave`);
    }
    for (const p of people) {
      const c = count.get(p.name);
      if (crew.includes(p.name)) {
        c.total++; if (isWeekend(d)) c.weekend++;
        if (++c.run === MAX_RUN + 1) out.push(`${d}: ${p.name} works a ${MAX_RUN + 1}th day in a row`);
      } else c.run = 0;
    }
  }
  for (const s of shares(people, start, n)) {
    const c = count.get(s.name);
    if (Math.abs(c.total - s.total) > TOTAL_SLACK + EPS)
      out.push(`${s.name}: ${c.total} shifts, fair share ${s.total.toFixed(2)}`);
    if (Math.abs(c.weekend - s.weekend) > WEEKEND_SLACK + EPS)
      out.push(`${s.name}: ${c.weekend} weekend shifts, share ${s.weekend.toFixed(2)}`);
  }
  return out;
}

