import { execFileSync, spawnSync } from 'node:child_process';
import { readFileSync } from 'node:fs';
import { makeRota } from './lib/assign.mjs';
import { days, isWeekend } from './lib/calendar.mjs';
import { checkRota, shares } from './lib/policy.mjs';
import { loadPeople, validatePeople } from './lib/people.mjs';

let bad = 0;
const ok = (name, cond, detail = '') => { if (!cond) bad++; console.log(`${cond ? 'ok  ' : 'FAIL'} ${name}${!cond && detail ? `\n     ${detail}` : ''}`); };
const throws = (fn, re) => { try { fn(); return false; } catch (e) { return re.test(e.message); } };
const team = (rows) => validatePeople(rows.map(([name, role, fte = 1, leave = []]) => ({ name, role, fte, leave })));
const shiftsOf = (rota, name, weekendOnly = false) =>
  Object.entries(rota).filter(([d, c]) => c.includes(name) && (!weekendOnly || isWeekend(d))).length;

// Calendar
ok('seven days', days('2026-11-02', 7).length === 7);
ok('Saturday is a weekend', isWeekend('2026-11-07') && !isWeekend('2026-11-06'));
ok('days cross a month and year end', days('2026-12-30', 4).join() === '2026-12-30,2026-12-31,2027-01-01,2027-01-02');

// The original small cases still hold
const small = team([['Ana', 'nurse'], ['Bea', 'aide', 1, ['2026-11-03']], ['Cy', 'nurse']]);
const r = makeRota(small, '2026-11-02', 7);
ok('two people a day', Object.values(r).every((d) => d.length === 2 && new Set(d).size === 2));
ok('a nurse every day', Object.values(r).every((d) => d.some((n) => small.find((p) => p.name === n).role === 'nurse')));
ok('leave is honoured', !r['2026-11-03'].includes('Bea'));

// The checker itself catches each kind of breach (otherwise the tests below prove nothing)
{
  const t = team([['N1', 'nurse'], ['N2', 'nurse'], ['A1', 'aide', 1, ['2026-11-02']]]);
  // 14 days: N2's weekend share is 2.9, so zero weekend shifts is a breach (over 7 days it is 1.4, which is not).
  const breaches = checkRota(t, '2026-11-02', 14, Object.fromEntries(days('2026-11-02', 14).map((d) => [d, ['A1', 'N1']])));
  ok('checker: leave', breaches.some((b) => /A1 is on leave/.test(b)));
  ok('checker: rest', breaches.some((b) => /6th day in a row/.test(b)));
  ok('checker: fair share', breaches.some((b) => /N2: 0 shifts/.test(b)));
  ok('checker: weekend share', breaches.some((b) => /N2: 0 weekend/.test(b)));
  const noNurse = checkRota(t, '2026-11-02', 1, { '2026-11-02': ['A1', 'A1'] });
  ok('checker: cover and nurse', noNurse.some((b) => /different/.test(b)) && noNurse.some((b) => /no nurse/.test(b)));
}

// Shares follow the policy formula
{
  const t = team([['N', 'nurse', 1], ['H', 'nurse', 0.5, days('2026-11-02', 14)], ['A', 'aide', 1]]);
  const s = shares(t, '2026-11-02', 28); // weights 1, 0.25, 1 → 56 shifts split 4:1:4
  ok('shares use fte × days not on leave', Math.abs(s[0].total - 24.888888) < 1e-5 && Math.abs(s[1].total - 6.222222) < 1e-5);
  ok('weekend shares use the same weights', Math.abs(s[1].weekend - 16 / 9) < 1e-9);
}

// The clinic's real team: the complaint that started this
{
  const people = loadPeople(new URL('./people.json', import.meta.url));
  const rota = makeRota(people, '2026-11-02', 28);
  const breaches = checkRota(people, '2026-11-02', 28, rota);
  ok('clinic team, November: meets every rule', breaches.length === 0, breaches.join('; '));
  ok('Ana does not work every day', shiftsOf(rota, 'Ana') < 28);
  ok('Yusuf gets weekends', shiftsOf(rota, 'Yusuf', true) >= 1);
  ok('every member works', people.every((p) => shiftsOf(rota, p.name) > 0));
}

// Period after period. Each rota can be lawful while the same people come out ahead every time:
// that is the original complaint at a smaller size. Before the integer targets, 26 four-week rotas
// with no leave left Yusuf 26 shifts over his share and Marta and Pete about 20 under.
{
  const people = loadPeople(new URL('./people.json', import.meta.url)).map((p) => ({ ...p, leave: new Set() }));
  const drift = new Map(people.map((p) => [p.name, 0]));
  const wDrift = new Map(people.map((p) => [p.name, 0]));
  const wkShiftsOf = (rota, name) => Object.entries(rota).filter(([d, c]) => isWeekend(d) && c.includes(name)).length;
  let start = '2026-11-30', lawful = true;
  for (let r = 0; r < 26; r++) {
    const rota = makeRota(people, start, 28);
    lawful &&= checkRota(people, start, 28, rota).length === 0;
    for (const s of shares(people, start, 28)) {
      drift.set(s.name, drift.get(s.name) + shiftsOf(rota, s.name) - s.total);
      wDrift.set(s.name, wDrift.get(s.name) + wkShiftsOf(rota, s.name) - s.weekend);
    }
    start = days(start, 29).at(-1);
  }
  const worst = Math.max(...[...drift.values()].map(Math.abs));
  ok(`clinic team, 26 periods: nobody drifts more than 5 shifts from their share (worst ${worst.toFixed(1)})`, lawful && worst <= 5,
    [...drift].map(([k, v]) => `${k} ${v.toFixed(1)}`).join(', '));
  // Weekends were the stubborn half: exact weekend targets used to time out in ~1 period in 3, and
  // the fallback handed the spare weekend to the same aide each time (Pete +19, Marta -18 over 52).
  // With restarts the targets are met every period; worst over 26 is 3.0.
  const wWorst = Math.max(...[...wDrift.values()].map(Math.abs));
  ok(`clinic team, 26 periods: nobody drifts more than 4 weekend shifts from their share (worst ${wWorst.toFixed(1)})`, wWorst <= 4,
    [...wDrift].map(([k, v]) => `${k} ${v.toFixed(1)}`).join(', '));
}

// The CLI
{
  const out = execFileSync('node', ['cli.mjs', 'people.json', '2026-11-02', '28'], { cwd: new URL('.', import.meta.url) }).toString();
  const rota = JSON.parse(out);
  ok('cli prints one key per date', Object.keys(rota).join() === days('2026-11-02', 28).join());
  const fail = spawnSync('node', ['cli.mjs', 'people.json', 'not-a-date', '28'], { cwd: new URL('.', import.meta.url) });
  ok('cli exits non-zero with a message', fail.status !== 0 && /rota: bad start date/.test(fail.stderr.toString()));
}

// "Any team and period": many random teams, each checked against every rule
{
  let seed = 12345;
  const rand = () => ((seed = (seed * 1103515245 + 12345) % 2147483648) / 2147483648);
  let tried = 0, built = 0, refused = 0;
  const failures = [];
  for (let trial = 0; trial < 60; trial++) {
    const n = 7 + Math.floor(rand() * 50);
    const start = days('2026-01-01', 1 + Math.floor(rand() * 365)).at(-1);
    const period = days(start, n);
    const size = 4 + Math.floor(rand() * 7);
    const rows = Array.from({ length: size }, (_, i) => {
      const leave = [];
      if (rand() < 0.4) { const from = Math.floor(rand() * n); leave.push(...period.slice(from, from + 1 + Math.floor(rand() * 5))); }
      return [`P${i}`, i < 2 || rand() < 0.4 ? 'nurse' : 'aide', [1, 1, 0.8, 0.6, 0.5][Math.floor(rand() * 5)], leave];
    });
    const t = team(rows);
    tried++;
    try {
      const rota = makeRota(t, start, n);
      built++;
      const b = checkRota(t, start, n, rota);
      if (b.length) failures.push(`trial ${trial}: ${b[0]}`);
    } catch (e) {
      // A refusal is acceptable only when it names a real impossibility in the policy itself.
      refused++;
      if (!/^(policy conflict|no nurse available|fewer than 2)/.test(e.message)) failures.push(`trial ${trial} refused: ${e.message}`);
    }
  }
  ok(`random teams: ${built}/${tried} built and compliant, ${refused} refused as impossible`, failures.length === 0 && built >= 50, failures.slice(0, 3).join('; '));
}

// Edge cases
{
  const t = team([['N1', 'nurse'], ['N2', 'nurse'], ['A1', 'aide', 1, days('2026-11-02', 28)], ['A2', 'aide']]);
  const rota = makeRota(t, '2026-11-02', 28);
  ok('someone on leave all period gets no shifts and is not owed any', shiftsOf(rota, 'A1') === 0 && checkRota(t, '2026-11-02', 28, rota).length === 0);
  const one = makeRota(team([['N1', 'nurse'], ['A1', 'aide']]), '2026-11-07', 1);
  ok('a one-day period works', checkRota(team([['N1', 'nurse'], ['A1', 'aide']]), '2026-11-07', 1, one).length === 0);
}

